import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Claim {
  id: number;
  personId: number;
  /** The amount with two decimals, as text (e.g. "10.50"). */
  amount: string;
  /** YYYY-MM-DD */
  date: string;
  /** The date (YYYY-MM-DD) the claim is due by: the terms-th business day after its date when it was
   *  added, with the terms fixed then, skipping weekends and the sheet's holidays now. */
  dueBy: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on the sheet, given when it is opened (sheet-wide, e.g. "3", or within its
   *  period, e.g. "P1-2", or "X-1" in no period); null while DRAFT. */
  number: string | null;
  /** What was due on the claim when it was settled, with two decimals; null otherwise, and when its
   *  person's grade had no rate then. */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. */
  openedBy: string | null;
  /** Whether the claim is bound to the figure it had at its person's last statement. */
  stated: boolean;
  /** The figure it is bound to, with two decimals; null while unbound, and when it had no figure
   *  (no rate) then. */
  statedDue: string | null;
  /** On a correction (a claim with a negative amount), the number of the SETTLED claim of the same
   *  person it corrects; null on any other claim. */
  corrects: string | null;
  /** The claim's status log, oldest first: one line per status it has had, as
   *  "<STATUS> by <user> on <date> due=<due>", with the sheet's today and what was due on it then. */
  log: string[];
  /** The date (YYYY-MM-DD) the claim was last deferred until; null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs the claim has been given. */
  proofs: number;
  /** The number of the claim this one was split off; null when it was not split off another. */
  splitFrom: string | null;
  /** Whether the claim was added while the period its date falls in was soft-closed. */
  lateEntry: boolean;
  /** The sheet's today (YYYY-MM-DD) on which a reminder of the claim was last written; null when
   *  none ever was. */
  remindedOn: string | null;
}

/** Added as DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it PENDING
 *  until a steward approves it (SETTLED) or rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim
 *  can be VOID, and a SETTLED one by a steward within 7 days of its settlement (it keeps its settled
 *  figure, which leaves every total). */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A status change asked of a claim. */
export type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void';

/** Whether a claim in this status counts toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** The status the claim had at the end of the day (YYYY-MM-DD), as its status log records it
 *  (each line dated with the sheet's today when the change was made); null when it was added after. */
export function statusOn(claim: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of claim.log) {
    const [, logged, on] = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S+$/.exec(line) ?? [];
    if (on === undefined || on > day) break;
    status = logged as ClaimStatus;
  }
  return status;
}

/** Whether a claim is still open: OPEN, or PENDING, which is handled like OPEN (it goes overdue,
 *  bears the late charge and leaves the totals while its person is on hold). */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether a claim is deferred on the sheet's today: OPEN and deferred until a date after it. Until
 *  then it counts in no total, is not overdue, cannot be settled and no statement binds it. */
export function deferred(claim: Claim, today: string | null): boolean {
  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
}

/** Whether a claim is overdue: OPEN or PENDING, not deferred, and due by a date before the sheet's today. */
export function overdue(claim: Claim, today: string | null): boolean {
  return isOpen(claim) && today !== null && !deferred(claim, today) && claim.dueBy < today;
}

/** How a bulk open went: how many claims it opened and refused, and the claims it opened. */
export interface BulkOpened {
  opened: number;
  refused: number;
  claims: Claim[];
}

/** How a bulk settle went: how many it settled (or left PENDING) and refused, and those claims. */
export interface BulkSettled {
  settled: number;
  refused: number;
  claims: Claim[];
}

/** How a paste of claims went: how many it added, and the claims, in the order of their lines. */
export interface Pasted {
  added: number;
  claims: Claim[];
}

export interface ClaimFields {
  amount: string;
  /** null takes the sheet's today. */
  date: string | null;
  note: string;
  /** The number of the claim a correction corrects; null on a claim that is not a correction. */
  corrects: string | null;
}

/** Whether a claim is a correction: one with a negative amount. */
export function isCorrection(claim: Claim): boolean {
  return cents(claim.amount) < 0;
}

/** Amounts in whole cents, so sums of two-decimal amounts are exact. */
export function cents(amount: string): number {
  return Math.round(Number(amount) * 100);
}

export function money(cents: number): string {
  return (cents / 100).toFixed(2);
}

// The claims kept on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class ClaimsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  if (remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n))) quotient += 1n;
  return Number(negative ? -quotient : quotient);
}

/** Whether a claim keeps the figure fixed when it was settled at a rate: it is SETTLED, or was voided
 *  once settled, and has one. */
function isFrozen(claim: Claim): boolean {
  return claim.settledDue !== null && (claim.status === 'SETTLED' || claim.status === 'VOID');
}

/** The figure of a claim, in cents: a claim settled at a rate keeps what was due on it then (and once voided); a
 *  claim a statement bound keeps, unless it is PENDING (no statement binds it while it is), the figure it was bound to (null when that was none); otherwise
 *  what is due on its amount at the rate in force on the claim's date of the grade in force
 *  for its person then, rounded as the claim rounds (see roundsHalfUp) — the rate figure alone,
 *  before any late charge or floor (see claimShownCents); null when no rate applies then. */
export function claimDueCents(
  claim: Claim,
  rates: Rate[],
  grades: PersonGrade[],
  rounding: Rounding,
): number | null {
  if (isFrozen(claim) && claim.settledDue !== null) return cents(claim.settledDue);
  if (claim.stated && claim.status !== 'PENDING') return claim.statedDue === null ? null : cents(claim.statedDue);
  const grade = gradeOn(grades, claim.date);
  return grade === null ? null : dueCents(cents(claim.amount), rateOn(rates, grade, claim.date), roundsHalfUp(claim, rounding));
}

/** What a late charge is worked from: the sheet's today and every late percent recorded, oldest
 *  first, with two decimals. */
export interface Lateness {
  today: string | null;
  latePcts: readonly Dated[];
}

/** The late charge on a claim whose figure is figureCents, in cents: for every full 30 days the claim
 *  is overdue (OPEN or PENDING, not deferred, and past its due-by on the sheet's today), the late
 *  percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of that figure, rounded
 *  like the claim's due, the charges added up (a boundary whose percent is 0.00 adds nothing); 0 on any other claim, and on a correction. A statement never binds it; settling fixes it in. */
export function lateChargeCents(claim: Claim, figureCents: number, late: Lateness, rounding: Rounding): number {
  if (!isOpen(claim) || late.today === null || isCorrection(claim) || deferred(claim, late.today)) return 0;
  const days = (Date.parse(late.today) - Date.parse(claim.dueBy)) / 86_400_000;
  const periods = Math.max(0, Math.floor(days / 30));
  const dueBy = Date.parse(claim.dueBy);
  let charge = 0;
  for (let k = 1; k <= periods; k++) {
    const boundary = new Date(dueBy + k * 30 * 86_400_000).toISOString().slice(0, 10);
    const latePct = inForce(late.latePcts, boundary, LATE_PCT);
    if (Number(latePct) === 0) continue;
    charge += dueCents(figureCents, latePct, roundsHalfUp(claim, rounding)) ?? 0;
  }
  return charge;
}

/** What is due on a claim as it shows and totals, in cents: a claim settled at a rate keeps what was
 *  due on it then; otherwise the greater of the sheet's floor in force on the claim's date and its
 *  figure (see claimDueCents) plus its late charge (a correction has neither); null when it has no
 *  figure. `floors` is every floor recorded, oldest first. */
export function claimShownCents(
  claim: Claim,
  rates: Rate[],
  grades: PersonGrade[],
  floors: readonly Dated[],
  late: Lateness,
  rounding: Rounding,
): number | null {
  const figure = claimDueCents(claim, rates, grades, rounding);
  if (figure === null || isCorrection(claim)) return figure;
  if (isFrozen(claim)) return figure;
  return Math.max(figure + lateChargeCents(claim, figure, late, rounding), cents(inForce(floors, claim.date, FLOOR)));
}

// The rates of the grades on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class RatesService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheet: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheet), { headers: this.session.headers() }));
  }

  /** A null from sets the rate that applies from the beginning of time; a null to, one with no end. */
  set(sheet: string, grade: Grade, pct: string, from: string | null, to: string | null): Promise<Rate> {
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheet)}/${grade}`, { pct, from, to }, { headers: this.session.headers() }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/rates`;
  }
}

