    public Optional<String> valueOn(String key, LocalDate on) {
        return settings.stream()
                .filter(s -> s.getKey().equals(key) && !s.getFrom().isAfter(on))
                .max(Comparator.comparing(SheetSetting::getFrom))
                .map(SheetSetting::getValue);
    }
}
